24	// Agent implements agent.Agent by delegating to an external binary.
25	// Each method invokes a subcommand on the binary and parses the JSON response.
26	type Agent struct {
27		binaryPath string
28		info       *InfoResponse
29	}
30	
31	// New creates an Agent by calling the binary's "info" subcommand
32	// to cache its metadata. Returns an error if the binary cannot be invoked or returns
33	// invalid/incompatible protocol data. The provided context bounds the "info" call;
34	// pass a context with a deadline to limit how long discovery waits for each binary.
35	func New(ctx context.Context, binaryPath string) (*Agent, error) {
36		ea := &Agent{binaryPath: binaryPath}
37	
38		stdout, err := ea.run(ctx, nil, "info")
39		if err != nil {
40			return nil, fmt.Errorf("info: %w", err)
41		}
42	
43		var info InfoResponse
44		if err := json.Unmarshal(stdout, &info); err != nil {
45			return nil, fmt.Errorf("info: invalid JSON: %w", err)
46		}
47	
48		if info.ProtocolVersion != ProtocolVersion {
49			return nil, fmt.Errorf("protocol version mismatch: binary reports %d, expected %d",
50				info.ProtocolVersion, ProtocolVersion)
51		}
52	
53		ea.info = &info
54		return ea, nil
55	}
